5	namespace AtrioTeam\DigitalHub\Filament\Concerns;
6	
7	use Filament\Resources\Resource;
8	use Illuminate\Contracts\Support\Htmlable;
9	use Illuminate\Database\Eloquent\Model;
10	
11	/**
12	 * Breadcrumb "solo record" per le list page nidificate: mostra la label della
13	 * risorsa radice (link al suo indice) seguita dai soli titoli dei record
14	 * antenati (gruppo, categoria, …). Omette le label delle risorse intermedie e
15	 * il "Lista" finale della pagina.
16	 *
17	 * Es. lista tag di "Colore" in "Tag prodotto": Tag anagrafiche / Tag prodotto / Colore
18	 *
19	 * @mixin \Filament\Resources\Pages\ListRecords
20	 */
21	trait HasRecordOnlyBreadcrumbs
22	{
23	    /**
24	     * @return array<string>
25	     */
26	    public function getBreadcrumbs(): array
27	    {
28	        /** @var class-string<Resource> $resource */
29	        $resource = static::getResource();
30	        $registration = $resource::getParentResourceRegistration();
31	        $record = $this->getParentRecord();
32	
33	        // antenati [resourceClass, record] dal padre immediato risalendo
34	        /** @var list<array{class-string<Resource>, Model}> $ancestors */
35	        $ancestors = [];
36	
37	        while ($registration && $record instanceof Model) {
38	            /** @var class-string<Resource> $parentResource */
39	            $parentResource = $registration->getParentResource();
40	            $ancestors[] = [$parentResource, $record];
41	
42	            $registration = $parentResource::getParentResourceRegistration();
43	            $related = $registration ? $record->{$registration->getInverseRelationshipName()} : null;
44	            $record = $related instanceof Model ? $related : null;
45	        }
46	
47	        // pagina top-level (nessun parent): solo la label della risorsa
48	        if ($ancestors === []) {
49	            return [$resource::getBreadcrumb()];
50	        }
51	
52	        // dalla radice al padre immediato
53	        $ancestors = array_reverse($ancestors);
54	
55	        [$rootResource] = $ancestors[0];
56	
57	        $rootUrl = $rootResource::getUrl('index', shouldGuessMissingParameters: true);
58	
59	        $breadcrumbs = [
60	            $rootUrl => $rootResource::getBreadcrumb(),
61	        ];
62	
63	        $lastAncestor = array_key_last($ancestors);
64	
65	        foreach ($ancestors as $index => [$ancestorResource, $ancestorRecord]) {
66	            $title = $ancestorResource::getRecordTitle($ancestorRecord);
67	            $label = $title instanceof Htmlable ? $title->toHtml() : (string) $title;
68	
69	            // il padre immediato è cliccabile: porta alla sua lista (i record
70	            // fratelli). Il parametro del nonno è risolto dalla route corrente.
71	            // Se però la sua lista coincide con il root (nidificazione a un solo
72	            // livello) resta testo semplice, per non sovrascrivere il root.
73	            $url = $index === $lastAncestor
74	                ? $ancestorResource::getUrl('index', shouldGuessMissingParameters: true)
75	                : null;
76	
77	            if ($url !== null && $url !== $rootUrl) {
78	                $breadcrumbs[$url] = $label;
79	            } else {
80	                $breadcrumbs[] = $label;
81	            }
82	        }
83	
84	        return $breadcrumbs;
85	    }
86	
87	    /**
88	     * Titolo pagina: ultimo livello delle breadcrumb (titolo del record padre
89	     * immediato, es. "Colore"). Sulle pagine top-level ricade sulla label della
90	     * risorsa.
91	     */
92	    public function getTitle(): string
93	    {
94	        $breadcrumbs = $this->getBreadcrumbs();
95	
96	        return (string) end($breadcrumbs);
97	    }
98	}
