5	namespace App\Filament\Resources\Products\Pages;
6	
7	use App\Filament\Resources\Category1s\Category1Resource;
8	use App\Filament\Resources\Category2s\Category2Resource;
9	use App\Filament\Resources\Products\ProductResource;
10	use App\Models\Category2;
11	use AtrioTeam\DigitalHub\Filament\Concerns\IsDigitalHubListPage;
12	use Filament\Resources\Pages\ListRecords;
13	use Illuminate\Database\Eloquent\Builder;
14	use Illuminate\Database\Eloquent\Relations\Relation;
15	use Override;
16	
17	class ListProducts extends ListRecords
18	{
19	    use IsDigitalHubListPage;
20	
21	    protected static string $resource = ProductResource::class;
22	
23	    /**
24	     * @return Builder<\Illuminate\Database\Eloquent\Model>|Relation<\Illuminate\Database\Eloquent\Model, \Illuminate\Database\Eloquent\Model, *>|null
25	     */
26	    #[Override]
27	    protected function getTableQuery(): Builder|Relation|null
28	    {
29	        $query = parent::getTableQuery();
30	        $category2Id = request()->query('category_2');
31	
32	        if ($query !== null && is_string($category2Id) && $category2Id !== '') {
33	            $query->where('category_2_id', (int) $category2Id);
34	        }
35	
36	        return $query;
37	    }
38	
39	    /** @return array<string|int, string> */
40	    #[Override]
41	    public function getBreadcrumbs(): array
42	    {
43	        $category2Id = request()->query('category_2');
44	        if (! is_string($category2Id) || $category2Id === '') {
45	            return parent::getBreadcrumbs();
46	        }
47	
48	        $category2 = Category2::query()->with('category1')->find((int) $category2Id);
49	        if ($category2 === null) {
50	            return parent::getBreadcrumbs();
51	        }
52	
53	        $crumbs = [Category1Resource::getUrl('index') => __('category1.model_plural')];
54	
55	        if ($category2->category1 !== null) {
56	            $crumbs[Category2Resource::getUrl('index', ['category_1' => $category2->category1->id])] = $category2->category1->name;
57	        }
58	
59	        $crumbs['#'] = $category2->name;
60	        $crumbs[] = __('product.model_plural');
61	
62	        return $crumbs;
63	    }
64	
65	
66	}
